import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {inflateSync} from 'node:zlib';

export async function runMotionDropCascadeSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));let revision=0;
 async function ready(count=4){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&d.querySelectorAll('.nw-drop-card').length===count&&d.querySelector('[data-motion-canvas]')&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{timeout:15000},count);}
 async function change(selector,value,count=4){const mark='drop-'+(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.dropOld=mark;n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.dropOld!==mark&&d.querySelector('.nw-drop-card');},{timeout:10000},mark);await ready(count);}
 async function pose(progress,selector='.nw-motion-dialog iframe',gid){return page.$eval(selector,(f,{progress,gid})=>{const d=f.contentDocument,id=gid||d.querySelector('.sc').dataset.id;f.contentWindow.__NAG_SCROLL_DIRECTOR[id].set(progress);return Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,src:n.querySelector('img').getAttribute('src'),phase:n.dataset.nwStreamPhase,angle:+n.dataset.nwDropAngle,arrival:+n.dataset.nwDropArrival,alpha:+n.querySelector('canvas').style.opacity,left:n.style.left,top:n.style.top,width:n.style.width,height:n.style.height}));},{progress,gid});}
 async function actualScroll(selector,gid){await page.$eval(selector,f=>f.contentWindow.scrollTo(0,f.contentDocument.querySelector('.sc').offsetHeight/2-f.contentWindow.innerHeight/2));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()>.4,{},{selector,gid});const middle=await page.$eval(selector,(f,gid)=>({p:f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress(),phase:+f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase}),gid);assert.ok(Math.abs(middle.phase-(middle.p*100-20)/60*3)<.001);await page.$eval(selector,f=>f.contentWindow.scrollTo(0,0));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()<.05,{},{selector,gid});assert.equal(await page.$eval(selector,f=>f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase),'0.000000');}
 async function exported(gid){await page.evaluate(()=>{document.querySelector('#drop-export')?.remove();const f=document.createElement('iframe');f.id='drop-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#drop-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&document.querySelector('#drop-export').contentDocument.querySelector('.nw-drop-card'),{},gid);}
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,bg:'#527467',elements:[mkEl('label',{text:'Exterior',name:'Exterior'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0]}));
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="cascade-drop"]');await ready();assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'7');assert.equal(await page.$eval('[data-motion-stream-count]',n=>[n.min,n.max].join(',')),'2,8');assert.equal(await page.$eval('[data-motion-stream="rotation"]',n=>[n.value,n.min,n.max].join(',')),'100,0,200');assert.equal(await page.$eval('[data-motion-stream="cardSize"]',n=>[n.value,n.min,n.max].join(',')),'78,50,95');assert.equal(await page.$eval('[data-motion-stream="backgroundType"]',n=>n.value),'none');assert.equal(await page.$eval('[data-motion-stream="cardRatio"]',n=>n.value),'1:1');
  const start=await pose(0),end=await pose(1);assert.deepEqual(start.map(({phase,...n})=>n),end.map(({phase,...n})=>n));assert.ok(start.every(n=>n.alpha===0));const hold=await pose(.72);assert.ok(hold.every(n=>n.alpha===1&&n.arrival===1));assert.deepEqual(hold.map(({phase,...n})=>n),(await pose(.78)).map(({phase,...n})=>n));assert.ok((await pose(.999)).every(n=>n.alpha===0));
  await change('[data-motion-stream="rotation"]','0');assert.ok((await pose(.72)).every(n=>n.angle===0));await change('[data-motion-stream="rotation"]','200');assert.ok((await pose(.72)).some(n=>Math.abs(n.angle)>3));for(const cardRatio of ['frame','16:9','9:16','1:1'])await change('[data-motion-stream="cardRatio"]',cardRatio);await change('[data-motion-stream="cardSize"]','95');await change('[data-motion-stream="padding"]','0');
  const reuse=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,clock=f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id];for(let i=0;i<60;i++)clock.set(i/60);const native=d.createElement;let created=0;d.createElement=function(...args){if(args[0]==='canvas')created++;return native.apply(this,args);};try{for(let i=0;i<60;i++)clock.set(i/60);return created;}finally{d.createElement=native;}});assert.equal(reuse,0,'Cards reuse textures while falling and sweeping');
  await change('[data-motion-stream-count]','4');await pose(.72);await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/cascade-drop-desktop.png'});
  await change('[data-motion-stream-count]','2',2);await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true);await change('[data-motion-stream-count]','4');assert.deepEqual((await pose(0)).map(n=>[n.id,n.src]),start.map(n=>[n.id,n.src]));await change('[data-motion-stream-count]','8',8);await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-duplicate]',n=>n.disabled),true);await change('[data-motion-stream-count]','4');await change('[data-motion-stream="rotation"]','175');assert.notDeepEqual(await pose(.15),start);await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="turns"]','3');await change('[data-motion-stream="start"]','20');await change('[data-motion-stream="end"]','80');await change('[data-motion-stream="scrollLength"]','420');assert.equal((await pose(.1))[0].phase,'0.000000');assert.equal((await pose(.5))[0].phase,'1.500000');assert.equal((await pose(.9))[0].phase,'3.000000');assert.deepEqual((await pose(.1)).map(({phase,...n})=>n),(await pose(.9)).map(({phase,...n})=>n));assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',n=>n.value='Mi Pila');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.stream.kind,'cascade-drop');assert.equal(saved.config.stream.rotation,175);assert.equal(saved.assets.length,4);await page.click('[data-motion-saved="'+saved.id+'"]');await ready();const copied=await pose(.35);assert.ok(copied.every(n=>!start.some(o=>o.id===n.id)));assert.deepEqual(copied.map(n=>n.src),start.map(n=>n.src));await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,project:JSON.stringify(project),group:g,outside:sec().elements[0],length:sec().sdLength,enabled:sec().sdEnabled};});assert.equal(inserted.enabled,true);assert.equal(inserted.length,420);assert.equal(inserted.group.bg,'transparent');assert.deepEqual(inserted.outside,before.outside);await page.waitForFunction(id=>document.querySelector('#preview')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id]&&document.querySelector('#preview').contentDocument.querySelector('.nw-drop-card'),{},inserted.gid);await actualScroll('#preview',inserted.gid);await exported(inserted.gid);assert.deepEqual((await pose(.35,'#drop-export',inserted.gid)).map(n=>n.src),copied.map(n=>n.src));await page.$eval('#drop-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].live(),inserted.gid);await actualScroll('#drop-export',inserted.gid);await page.evaluate(()=>document.querySelector('#drop-export').remove());
  await page.evaluate(id=>{NAGWEB_SCROLL_DIRECTOR.scrub(id,.25);NAGWEB_MOTION_LAB.edit(id);},inserted.gid);await ready();assert.equal(await page.$$eval('[data-motion-template]',ns=>ns.every(n=>n.disabled)),true);await change('[data-motion-stream="rotation"]','25');await page.$eval('#preview',f=>f.contentDocument.body.dataset.dropSaved='old');await page.click('[data-motion-save]');await page.waitForFunction(id=>{const f=document.querySelector('#preview');return f?.contentDocument?.body&&!f.contentDocument.body.dataset.dropSaved&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[id]&&f.contentDocument.querySelector('.nw-drop-card');},{},inserted.gid);await actualScroll('#preview',inserted.gid);const scroll=await page.evaluate(()=>JSON.stringify(project));
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();assert.equal(await page.$eval('[data-motion-stream="rotation"]',n=>n.value),'25');await change('[data-motion-config="source"]','time');await change('[data-motion-config="duration"]','2');await page.click('[data-motion-save]');const loop=await page.evaluate(()=>JSON.stringify(project));assert.equal(await page.evaluate(()=>sec().sdEnabled),false);await exported(inserted.gid);const clock=await page.$eval('#drop-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].progress(),inserted.gid);await page.waitForFunction(({gid,clock})=>document.querySelector('#drop-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()!==clock,{timeout:3000},{gid:inserted.gid,clock});assert.equal(await page.$eval('#drop-export',f=>!!f.contentDocument.querySelector('.nw-sd-active')),false);await page.evaluate(()=>document.querySelector('#drop-export').remove());await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),scroll);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);assert.equal(await page.evaluate(id=>migrate(JSON.parse(JSON.stringify(project))).pages[0].sections[0].elements.find(e=>e.id===id).nwMotionInstance.stream.kind,inserted.gid),'cascade-drop');
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="cascade-drop"]');await ready();await change('[data-motion-stream="frameRatio"]','auto');await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/cascade-drop-mobile.png'});await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="start"]','80');await change('[data-motion-stream="end"]','90');await change('[data-motion-stream="turns"]','0.25');await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);assert.deepEqual(await pose(.1),await pose(.9));assert.ok((await pose(.1)).every(n=>n.alpha===1&&n.arrival===1),'Reduced motion shows the settled pile even with a late, partial scroll cycle');await change('[data-motion-stream="turns"]','2');assert.ok((await pose(.9)).every(n=>n.alpha===1&&n.arrival===1),'Reduced motion stays settled across multiple cycles');await page.emulateMediaFeatures([]);await page.click('[data-motion-close]');await page.setViewport(viewport);assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="cascade-drop"]');await ready();await page.click('[data-motion-insert]');const newScene=await page.evaluate(()=>({gid:sec().nwMotionSceneGroup,config:sec().elements.find(e=>e.nwMotionInstance).nwMotionInstance}));assert.equal(newScene.config.template,'cascade-drop');assert.ok(newScene.gid);await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),newScene.gid);await ready();await page.click('[data-motion-close]');
  console.log('Cascade Drop: falls/settling/hold/sweep, controls and aspect ratios, texture reuse, 2–8 images/recovery, drafts/Library/unique IDs, real scroll after save, time loop, transparency, history/JSON/HTML, editable scene/group, mobile and reduced motion OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/cascade-drop-failure.png'}).catch(()=>{});throw error;}finally{await page.emulateMediaFeatures([]);await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#drop-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}

export async function runMotionDropCascadeDepthSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));let revision=0;
 async function ready(count=4){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelectorAll('.nw-drop-card').length===count&&d.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{timeout:15000},count);}
 async function change(key,value){const mark='drop-depth-'+(++revision);await page.$eval('[data-motion-stream="'+key+'"]',(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.dropDepthOld=mark;if(n.type==='checkbox')n.checked=value;else n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.dropDepthOld!==mark&&d.querySelector('.nw-drop-card');},{},mark);await ready();}
 function screenshotPixel(bytes){const png=Buffer.from(bytes),chunks=[];let channels;assert.equal(png.subarray(1,4).toString(),'PNG');for(let i=8;i<png.length;){const length=png.readUInt32BE(i),kind=png.subarray(i+4,i+8).toString(),data=png.subarray(i+8,i+8+length);if(kind==='IHDR'){assert.equal(data.readUInt32BE(0),1);assert.equal(data.readUInt32BE(4),1);assert.equal(data[8],8);assert.ok(data[9]===2||data[9]===6);channels=data[9]===2?3:4;}if(kind==='IDAT')chunks.push(data);i+=length+12;}const row=inflateSync(Buffer.concat(chunks));assert.ok(row[0]<=4);return Array.from(row.subarray(1,1+channels)).concat(channels===3?[255]:[]);}
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="cascade-drop"]');await ready();
  for(const [key,value] of [['rotation','200'],['cardSize','78'],['frameRatio','auto'],['cornerRadius','0'],['shadow',false]])await change(key,value);
  const colors=[[255,0,0],[0,255,0],[0,0,255],[255,255,0]];
  await page.$eval('[data-motion-stream-batch-upload]',(input,colors)=>{const transfer=new DataTransfer();colors.forEach((color,i)=>transfer.items.add(new File(['<svg xmlns="http://www.w3.org/2000/svg" width="300" height="300"><rect width="300" height="300" fill="rgb('+color.join(',')+')"/></svg>'],'Drop-depth-'+i+'.svg',{type:'image/svg+xml'})));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));},colors);await page.waitForFunction(()=>/Se cargaron 4/.test(document.querySelector('[data-motion-stream-batch-status]')?.textContent||''));await ready();
  for(const progress of [.4,.72,.88]){
   const probe=await page.$eval('.nw-motion-dialog iframe',(f,{progress,colors})=>{const d=f.contentDocument,nodes=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),host=nodes[0].offsetParent;f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id].set(progress);const clip=nodes[0].__nwMotionClip,tiles=nodes.map((n,slot)=>({id:n.dataset.id,slot,polygon:n.__nwMotionSurface,visible:n.__nwMotionVisible})).filter(t=>t.visible).reverse(),inside=(poly,x,y)=>{let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++)if((poly[i].y>y)!==(poly[j].y>y)&&x<(poly[j].x-poly[i].x)*(y-poly[i].y)/(poly[j].y-poly[i].y)+poly[i].x)hit=!hit;return hit;};for(let y=clip.top+8;y<clip.top+clip.height-8;y+=7)for(let x=clip.left+8;x<clip.left+clip.width-8;x+=7){const hits=tiles.filter(t=>inside(t.polygon,x,y));if(hits.length<2)continue;const top=hits[0];let edge=Infinity;for(let i=0;i<4;i++){const a=top.polygon[i],b=top.polygon[(i+1)%4];edge=Math.min(edge,Math.abs((b.y-a.y)*x-(b.x-a.x)*y+b.x*a.y-b.y*a.x)/Math.hypot(b.y-a.y,b.x-a.x));}if(edge<6)continue;const fr=f.getBoundingClientRect(),hr=host.getBoundingClientRect();return{id:top.id,slot:top.slot,expected:colors[top.slot],click:{x:fr.left+(hr.left+x)*fr.width/f.clientWidth,y:fr.top+(hr.top+y)*fr.height/f.clientHeight},overlaps:hits.length};}return null;},{progress,colors});
   assert.ok(probe,'Stacked cards have a visible overlap');assert.ok(probe.overlaps>=2);const pixel=screenshotPixel(await page.screenshot({type:'png',clip:{x:Math.floor(probe.click.x),y:Math.floor(probe.click.y),width:1,height:1}}));assert.equal(pixel[3],255);for(let i=0;i<3;i++)assert.ok(Math.abs(pixel[i]-probe.expected[i])<4,JSON.stringify({probe,pixel}));await page.mouse.click(probe.click.x,probe.click.y);assert.equal(await page.$eval('[data-motion-layer="'+probe.id+'"]',n=>n.getAttribute('aria-pressed')),'true');
  }
  console.log('Card Drop superposición: píxeles reales de archivos propios y clics coinciden con la tarjeta frontal durante dos lanzamientos OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/cascade-drop-depth-failure.png'}).catch(()=>{});throw error;}finally{await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}
